    return sha384(text.encode()).hexdigest()

def _sqlite_sha512(text):
    if text is None:
        return None
    return sha512(text.encode()).hexdigest()

def _sqlite_sign(x):
    if x is None:
        return None
    return (x > 0) - (x < 0)

def _sqlite_sin(x):
    if x is None:
        return None
    return sin(x)

def _sqlite_sqrt(x):
    if x is None:
        return None
    return sqrt(x)

def _sqlite_tan(x):
    if x is None:
        return None
    return tan(x)

class AnyValue(ListAggregate):
    def finalize(self):
        return self[0]

class BitAggregate(ListAggregate):
    bit_operator = None

    def finalize(self):
        items = (item for item in self if item is not None)
        try:
            return functools.reduce(self.bit_operator, items)
        except TypeError:
            # items may be an empty iterator when all elements are None.
            return None

class OperationDependency(
    namedtuple("OperationDependency", "app_label model_name field_name type")
):
    class Type(Enum):
        CREATE = 0
        REMOVE = 1
        ALTER = 2
        REMOVE_ORDER_WRT = 3
        ALTER_FOO_TOGETHER = 4
        REMOVE_INDEX_OR_CONSTRAINT = 5

    @cached_property
    def model_name_lower(self):
        return self.model_name.lower()

    @cached_property
    def field_name_lower(self):
        return self.field_name.lower()

class AmbiguityError(Exception):
